create or replace function aria_memory.reflect_mission_outcome(p_memory_id uuid,p_mission_id text,p_status text,p_goal text,p_completed_steps integer,p_total_steps integer,p_recovery_count integer) returns uuid language plpgsql security definer set search_path='' as $$ declare v_content text; v_hash text; v_lesson uuid; v_confidence numeric; begin if p_status='succeeded' then v_content := 'Reflection: mission '||p_mission_id||' succeeded. Reusable pattern candidate: complete '||coalesce(p_completed_steps,0)::text||' of '||coalesce(p_total_steps,0)::text||' steps for goal '||coalesce(p_goal,'')||'. Recovery count='||coalesce(p_recovery_count,0)::text||'.'; v_confidence := .95; elsif p_status='failed' then v_content := 'Reflection: mission '||p_mission_id||' failed. Failure pattern candidate for future planning. Completed '||coalesce(p_completed_steps,0)::text||' of '||coalesce(p_total_steps,0)::text||' steps. Goal='||coalesce(p_goal,'')||'. Recovery count='||coalesce(p_recovery_count,0)::text||'.'; v_confidence := .8; else v_content := 'Reflection: mission '||p_mission_id||' ended with status='||p_status||'. Treat as contextual experience, not a verified success.'; v_confidence := .7; end if; v_hash := encode(extensions.digest(v_content,'sha256'),'hex'); insert into aria_memory.memory_items(memory_type,title,content,content_hash,source_type,source_ref,provenance,metadata,confidence,importance,salience) values('lesson','Reflection for mission '||p_mission_id,v_content,v_hash,'mission',p_mission_id,jsonb_build_object('engine','reflection-v1','derived_from_memory_id',p_memory_id,'status',p_status),jsonb_build_object('mission_id',p_mission_id,'status',p_status,'completed_steps',p_completed_steps,'total_steps',p_total_steps,'recovery_count',p_recovery_count,'reusable_candidate',p_status='succeeded'),v_confidence,case when p_status='succeeded' then .9 else .75 end,.9) on conflict(content_hash) do update set updated_at=now() returning memory_id into v_lesson; insert into aria_memory.memory_relations(from_memory_id,to_memory_id,relation_type,strength,provenance) values(v_lesson,p_memory_id,'derived_from',v_confidence,jsonb_build_object('engine','reflection-v1')) on conflict(from_memory_id,to_memory_id,relation_type) do nothing; insert into aria_memory.memory_events(memory_id,event_type,source_ref,payload) values(v_lesson,'created',p_mission_id,jsonb_build_object('reflection','v1','source_memory_id',p_memory_id)); return v_lesson; end; $$;
revoke all on function aria_memory.reflect_mission_outcome(uuid,text,text,text,integer,integer,integer) from public,anon,authenticated;
grant execute on function aria_memory.reflect_mission_outcome(uuid,text,text,text,integer,integer,integer) to service_role;
create or replace function aria_memory.capture_mission_outcome() returns trigger language plpgsql security definer set search_path='' as $$ declare v_content text; v_hash text; v_id uuid; begin if tg_op <> 'UPDATE' then return new; end if; if new.status not in ('succeeded','failed','cancelled') or new.status=old.status then return new; end if; v_content := 'Mission '||new.mission_id||' finished with status='||new.status||'. Goal='||coalesce(new.goal,'')||'. Completed steps='||coalesce(new.completed_steps,0)::text||'/'||coalesce(new.total_steps,0)::text||'. Last command='||coalesce(new.last_command,'')||'. Exit code='||coalesce(new.last_exit_code::text,'null')||'. Next action='||coalesce(new.next_action,'')||'.'; v_hash := encode(extensions.digest(v_content,'sha256'),'hex'); insert into aria_memory.memory_items(memory_type,title,content,content_hash,source_type,source_ref,provenance,metadata,confidence,importance,salience) values('episodic','Mission outcome '||new.mission_id,v_content,v_hash,'mission',new.mission_id,jsonb_build_object('capture','mission_state_trigger','status',new.status,'mission_id',new.mission_id),jsonb_build_object('goal',new.goal,'status',new.status,'completed_steps',new.completed_steps,'total_steps',new.total_steps,'recovery_count',new.recovery_count),case when new.status='succeeded' then 1 else .85 end,.8,.9) on conflict(content_hash) do update set updated_at=now() returning memory_id into v_id; insert into aria_memory.memory_events(memory_id,event_type,source_ref,payload) values(v_id,'created',new.mission_id,jsonb_build_object('trigger','mission_state','status',new.status)); perform aria_memory.reflect_mission_outcome(v_id,new.mission_id,new.status,new.goal,new.completed_steps,new.total_steps,new.recovery_count); return new; end; $$;
drop trigger if exists trg_aria_memory_capture_mission_outcome on aria_internal.mission_state;
create trigger trg_aria_memory_capture_mission_outcome after update of status on aria_internal.mission_state for each row execute function aria_memory.capture_mission_outcome();
revoke all on function aria_memory.capture_mission_outcome() from public,anon,authenticated;
